import{_ as e,c as o,o as s,ah as r}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Favorites","description":"","frontmatter":{"title":"Favorites"},"headers":[],"relativePath":"store/favorite.md","filePath":"store/favorite.md"}'),a={name:"store/favorite.md"};function n(i,t,d,h,l,g){return s(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="favorites-pinia-stores" tabindex="-1">Favorites (Pinia stores) <a class="header-anchor" href="#favorites-pinia-stores" aria-label="Permalink to &quot;Favorites (Pinia stores)&quot;">​</a></h1><p><strong>Favorite stores</strong> are a persisted list of <strong>Pinia stores</strong> for faster navigation on <strong>Stores</strong>: starred rows move <strong>to the top</strong>, show a <strong>star</strong>, and a header badge counts how many favorites match the current results.</p><p>Store overview: <a href="/qa-tools/docs/store/general.html">Overview</a>.</p><p><strong>Vue component</strong> favorites (<strong>Props</strong> tab) are separate: <a href="/qa-tools/docs/props/favorite.html">Favorites (Props)</a>.</p><hr><h2 id="add-and-remove" tabindex="-1">Add and remove <a class="header-anchor" href="#add-and-remove" aria-label="Permalink to &quot;Add and remove&quot;">​</a></h2><ul><li><strong>In the store card</strong> — header <strong>star</strong> toggles favorite.</li><li><strong>Row context menu</strong> on <strong>Stores</strong> — add/remove favorite.</li><li><strong>Stores table</strong> — click the <strong>star</strong> area on a row.</li><li><strong>Options → Pinia Store → Favorite Stores</strong> — the list and its details card are below.</li></ul><p>Settings persist in the inspector profile with other options.</p><hr><h2 id="exact-names-and-wildcards" tabindex="-1">Exact names and wildcards <a class="header-anchor" href="#exact-names-and-wildcards" aria-label="Permalink to &quot;Exact names and wildcards&quot;">​</a></h2><p>Each entry defines a <strong>store name pattern</strong>.</p><ul><li>Without <strong><code>*</code></strong>, matching is <strong>exact</strong> and case-sensitive: the star appears only for that store name.</li><li><strong><code>*</code></strong> is any sequence, and the pattern must match the whole name. Example: <strong><code>use*Store</code></strong> matches <strong>useUserStore</strong> and <strong>useAuthStore</strong>. Case is significant.</li></ul><p>Removing favorite from a row clears <strong>all</strong> rules that match that store (exact and wildcard).</p><p>Manual entry in <strong>Options</strong> uses the same wildcard rules.</p><hr><h2 id="what-is-stored" tabindex="-1">What is stored <a class="header-anchor" href="#what-is-stored" aria-label="Permalink to &quot;What is stored&quot;">​</a></h2><p>Per entry the inspector keeps:</p><ul><li><strong>id</strong> and <strong>name</strong>, both set to the displayed store name when you star a row (a mask typed in Options is stored in these strings);</li><li><strong>storeId</strong> of the instance at the moment it was starred. The star does not use this field;</li><li><strong>time added</strong>.</li></ul><p>That lets favorites apply again after the store list rebuilds.</p><hr><h2 id="matching" tabindex="-1">Matching <a class="header-anchor" href="#matching" aria-label="Permalink to &quot;Matching&quot;">​</a></h2><p>The displayed name (<code>baseId</code>) is compared with each entry’s <strong>id</strong> and <strong>name</strong>. An exact equality or a <code>*</code> pattern on either field stars the row. Comparison is case-sensitive. The stored <strong>storeId</strong> is not part of the match.</p><p>If several stores match one mask, every matching row shows a star.</p><hr><h2 id="sorting-and-badge" tabindex="-1">Sorting and badge <a class="header-anchor" href="#sorting-and-badge" aria-label="Permalink to &quot;Sorting and badge&quot;">​</a></h2><p>The table keeps favorite rows on top.</p><p>The badge is always shown. It reads <code>0</code> when nothing is saved, otherwise visible favorites / saved total. It is yellow when at least one visible row is a favorite.</p><p>Clicking the badge opens <strong>Options → Pinia Store → Favorite Stores</strong>.</p><hr><h2 id="favorite-stores-in-options" tabindex="-1">Favorite Stores in Options <a class="header-anchor" href="#favorite-stores-in-options" aria-label="Permalink to &quot;Favorite Stores in Options&quot;">​</a></h2><p>The block is second on <strong>Options → Pinia Store</strong>. The add field placeholder is <strong>Store name (supports wildcards: <em>Store</em>)</strong>. <strong>Add</strong> or <strong>Enter</strong> trims the text and appends a row whose <strong>id</strong> and <strong>name</strong> are that string. There is no <strong>storeId</strong>. An empty value shows <strong>Name cannot be empty</strong>. The same <strong>id</strong> or <strong>name</strong> already in the list shows <strong>This store is already in favorites</strong>. That check is the exact string, so <code>Foo</code> and <code>foo</code> are two rows, and a mask is not treated as a duplicate of a name it would match.</p><p>Rows stay in the saved order.</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Store Name</strong></td><td>The stored name.</td></tr><tr><td><strong>Added</strong></td><td>The locale date only.</td></tr></tbody></table><p>The row menu (right click or <strong>⋮</strong>) is <strong>Edit</strong> and <strong>Delete</strong>. <strong>Delete</strong> removes every entry with that <strong>id</strong>. It does not clear other patterns that merely match the same store. The empty table says <em>No favorite stores</em>.</p><p>A click opens <strong>Favorite Store Details</strong>: <strong>Store Name</strong> and <strong>Added</strong> as the locale date and time. <strong>Edit</strong> in the row menu opens that card already in edit mode. The header <strong>Edit</strong> icon does the same on an open card. The field placeholder is <strong>Store name</strong>. <strong>Enter</strong> or <strong>Save</strong> writes the trimmed text into both <strong>id</strong> and <strong>name</strong> and keeps <strong>storeId</strong> if the row had one. <strong>Save</strong> is disabled while the field is blank, and it does not check for another row with the same name. <strong>Cancel</strong> leaves edit mode and stays on the card. <strong>Back</strong> or <strong>Escape</strong> closes the card, including during edit.</p><p>With nothing selected the panel says <em>Select an item to see details</em>. If the entry was removed while the card is open, it says <em>Item no longer exists</em>. Below <strong>1000</strong> px the card covers the settings list until you go back.</p><p>The card does not select that store on the Stores tab.</p><hr><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Favorite <strong>core</strong> stores: user, settings, UI shell.</li><li><strong>Patterns</strong> help uniform naming schemes; overly broad masks may over-select.</li><li>Favorites <strong>do not</strong> change Pinia runtime; they are local inspector metadata.</li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/store/general.html">Store overview</a></li><li><a href="/qa-tools/docs/props/favorite.html">Favorites (Props)</a></li><li><a href="/qa-tools/docs/options/customize.html">Customize</a></li></ul>',43)])])}const m=e(a,[["render",n]]);export{p as __pageData,m as default};
